// C#: catch (HttpRequestException ex) when (ex.StatusCode == TooManyRequests)

try {
  await callApi();
} catch (err) {
  if (err instanceof HttpError && err.status === 429) {
    await backoff();
    return;
  }
  if (err instanceof HttpError) {
    logger.error(err);
    throw err;
  }
  throw err;
}

